import 'package:flutter/material.dart'; import '../../services/storage_analytics_service.dart';
class StorageScreen extends StatefulWidget{const StorageScreen({super.key});@override State<StorageScreen> createState()=>_S();}
class _S extends State<StorageScreen>{late Future<StorageSummary> data=StorageAnalyticsService().scan(); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Storage')),body:FutureBuilder<StorageSummary>(future:data,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final x=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[Text('${(x.totalBytes/1073741824).toStringAsFixed(2)} GB indexed',style:Theme.of(context).textTheme.headlineMedium),ListTile(title:const Text('Photos'),trailing:Text('${x.photos}')),ListTile(title:const Text('Videos'),trailing:Text('${x.videos}')),ListTile(title:const Text('Possible duplicates'),trailing:Text('${x.duplicates}')),const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Free-up-space tools use local hashes and quality flags. Review every suggested deletion before confirming.')))]);}));}
